def _ias(lst):
    if lst is None:
        return None
    out = []
    for x in list(lst):
        try:
            out.append([int(v) for v in list(x)])
        except TypeError:
            getter = getattr(x, "getArray", None) or getattr(x, "to_array", None) or getattr(x, "get_array", None)
            out.append([int(v) for v in getter()] if callable(getter) else x)
    return out

def _sorted_ias(lst):
    got = _ias(lst)
    if got is None:
        return None
    return sorted(got)

def _term_str(t):
    if t is None:
        return None
    return str(t).replace(" ", "")

def _alg_card(alg):
    if alg is None:
        return None
    return int(alg.cardinality())

def _term_map():
    try:
        from java.util.concurrent import ConcurrentHashMap
        return ConcurrentHashMap()
    except ImportError:
        return {}

def _par_close(alg, gens):
    cl = Closer(alg, gens, True)
    setter = getattr(cl, 'setSuppressOutput', None) or getattr(cl, 'set_suppress_output', None)
    if callable(setter):
        setter(True)
    tm = _term_map()
    orig = cl.getTermMap()
    if orig is not None:
        try:
            tm.putAll(orig)
        except Exception:
            try:
                for k in orig:
                    tm[k] = orig[k]
            except Exception:
                pass
    return _sorted_ias(cl.sgCloseParallel(list(cl.getGenerators()), 0, tm))

